using UnityEngine;
using UnityEditor;

AssetDatabase.Refresh();
string spritePath = "Assets/TJGenerators/History/Sprite_20260809_230322.png";
var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(spritePath);
if (sprite == null) {
    AssetDatabase.ImportAsset(spritePath, ImportAssetOptions.ForceUpdate);
    sprite = AssetDatabase.LoadAssetAtPath<Sprite>(spritePath);
}
if (sprite == null) { Debug.LogError("精灵未找到: " + spritePath); return; }

// Remove any previous preview instance to keep idempotent
var old = GameObject.Find("GlandConfusion_Icon_Preview");
if (old != null) Object.DestroyImmediate(old);

var go = new GameObject("GlandConfusion_Icon_Preview");
var sr = go.AddComponent<SpriteRenderer>();
sr.sprite = sprite;
// Final sprite will be 256x256 (PPU=100 => 2.56 units at scale 1); scale 0.4 => ~1 unit icon
go.transform.position = new Vector3(0f, 1.5f, 0f);
go.transform.localScale = Vector3.one * 0.4f;

Undo.RegisterCreatedObjectUndo(go, "放置精灵");
var scene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
Debug.Log("GlandConfusion icon placeholder placed at (0,1.5,0) scale 0.4");

